    "sql": "SELECT\n  *,\n  CASE\n    WHEN BILL_AMT2 <= 368912.0000 AND PAY_0 <= 1.5000 THEN 0\n    WHEN BILL_AMT2 <= 368912.0000 AND PAY_0 > 1.5000 AND BILL_AMT1 <= 387.0000 THEN 0\n    WHEN BILL_AMT2 <= 368912.0000 AND PAY_0 > 1.5000 AND BILL_AMT1 > 387.0000 AND LIMIT_BAL <= 415000.0000 AND PAY_AMT5 <= 14000.0000 THEN 1\n    WHEN BILL_AMT2 <= 368912.0000 AND PAY_0 > 1.5000 AND BILL_AMT1 > 387.0000 AND LIMIT_BAL <= 415000.0000 AND PAY_AMT5 > 14000.0000 THEN 0\n    WHEN BILL_AMT2 <= 368912.0000 AND PAY_0 > 1.5000 AND BILL_AMT1 > 387.0000 AND LIMIT_BAL > 415000.0000 THEN 0\n    WHEN BILL_AMT2 > 368912.0000 THEN 1\n    ELSE 0\n  END AS prediccion\nFROM default_of_credit_card_clients;",
    "python": "def predict_c45(client):\n    \"\"\"\n    Predicción generada automáticamente por PyC45.\n    client: diccionario con los valores de las variables.\n    \"\"\"\n    if client.get('BILL_AMT2', 0.0) <= 368912.0000:\n        if client.get('PAY_0', 0.0) <= 1.5000:\n            return 0  # Hoja (n=934, prob=83.62%)\n        else:\n            if client.get('BILL_AMT1', 0.0) <= 387.0000:\n                return 0  # Hoja (n=3, prob=100.00%)\n            else:\n                if client.get('LIMIT_BAL', 0.0) <= 415000.0000:\n                    if client.get('PAY_AMT5', 0.0) <= 14000.0000:\n                        return 1  # Hoja (n=105, prob=78.10%)\n                    else:\n                        return 0  # Hoja (n=1, prob=100.00%)\n                else:\n                    return 0  # Hoja (n=1, prob=100.00%)\n    else:\n        return 1  # Hoja (n=6, prob=100.00%)",
    "fastapi": "from fastapi import FastAPI\nfrom pydantic import BaseModel\nimport uvicorn\n\napp = FastAPI(title='PyC45 Model API', version='1.0')\n\nclass ClientData(BaseModel):\n    LIMIT_BAL: float\n    SEX: float\n    EDUCATION: float\n    MARRIAGE: float\n    AGE: float\n    PAY_0: float\n    PAY_2: float\n    PAY_3: float\n    PAY_4: float\n    PAY_5: float\n    PAY_6: float\n    BILL_AMT1: float\n    BILL_AMT2: float\n    BILL_AMT3: float\n    BILL_AMT4: float\n    BILL_AMT5: float\n    BILL_AMT6: float\n    PAY_AMT1: float\n    PAY_AMT2: float\n    PAY_AMT3: float\n    PAY_AMT4: float\n    PAY_AMT5: float\n    PAY_AMT6: float\n\ndef predict_c45(client):\n    \"\"\"\n    Predicción generada automáticamente por PyC45.\n    client: diccionario con los valores de las variables.\n    \"\"\"\n    if client.get('BILL_AMT2', 0.0) <= 368912.0000:\n        if client.get('PAY_0', 0.0) <= 1.5000:\n            return 0  # Hoja (n=934, prob=83.62%)\n        else:\n            if client.get('BILL_AMT1', 0.0) <= 387.0000:\n                return 0  # Hoja (n=3, prob=100.00%)\n            else:\n                if client.get('LIMIT_BAL', 0.0) <= 415000.0000:\n                    if client.get('PAY_AMT5', 0.0) <= 14000.0000:\n                        return 1  # Hoja (n=105, prob=78.10%)\n                    else:\n                        return 0  # Hoja (n=1, prob=100.00%)\n                else:\n                    return 0  # Hoja (n=1, prob=100.00%)\n    else:\n        return 1  # Hoja (n=6, prob=100.00%)\n\n@app.post('/predict')\ndef predict(data: ClientData):\n    client_dict = data.dict()\n    pred = predict_c45(client_dict)\n    return {'prediction': pred}\n\nif __name__ == '__main__':\n    uvicorn.run(app, host='0.0.0.0', port=8000)"
